                "correta": 1,
                "explicacao": "Gabarito: <strong>F, V, F, F.</strong>. Fonte: EDUCA/2024. Assunto: colocacaoPronominal.",
                "banca": "EDUCA",
                "ano": 2024,
                "assunto": "Colocação Pronominal",
                "tipo": "multipla_escolha",
