                "correta": 1,
                "explicacao": "Gabarito: <strong>Errado</strong>. Fonte: Quadrix/2026. Assunto: nocoes_de_direito_geral.",
                "banca": "Quadrix",
                "ano": 2026,
                "assunto": "nocoes_de_direito_geral",
                "tipo": "certo_errado",
                "flashcard": null,
